using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int RateCeilingPoints = 10;

    public int For(LoyaltyTier tier, int subtotalCents)
    {
        var baseRate = tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 7,
            LoyaltyTier.Gold => 9
        };
        var bonus = subtotalCents switch
        {
            >= 20000 => 3,
            >= 5000 => 1,
            _ => 0
        };
        var rate = Math.Min(baseRate + bonus, RateCeilingPoints);
        return subtotalCents - subtotalCents * rate / 100;
    }
}
